name: PR Status Labeler

on:
  workflow_run:
    workflows: ["Capture PR Data"]
    types:
      - completed

permissions:
  pull-requests: write
  contents: read

jobs:
  label-pr:
    if: ${{ github.event.workflow_run.conclusion == 'success' }}
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Apply labels
        uses: actions/github-script@v6
        with:
          script: |
            const pr = ${{ github.event.workflow_run.pull_requests[0] }};
            if (!pr) {
              console.log('No pull request found in workflow_run event.');
              return;
            }
            const prNumber = pr.number;
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            // Example logic: add 'auto-label' label
            const labelsToAdd = ['auto-label'];
            await github.rest.issues.addLabels({
              owner,
              repo,
              issue_number: prNumber,
              labels: labelsToAdd
            });
            console.log(`Added labels ${labelsToAdd.join(', ')} to PR #${prNumber}.`);
